(8, 1, '2024-09-30 15:57:09', '2024-09-30 15:57:09', '<!-- wp:cover {\"url\":\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/cariboubanner-scaled.jpeg\",\"id\":79,\"dimRatio\":30,\"minHeight\":100,\"minHeightUnit\":\"vh\"} -->\n<div class=\"wp-block-cover\" style=\"min-height:100vh\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-30 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-79\" alt=\"\" src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/cariboubanner-scaled.jpeg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"className\":\"home-text\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group home-text\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette9\"}}}},\"textColor\":\"theme-palette9\",\"fontSize\":\"xxlarge\"} -->\n<h1 class=\"wp-block-heading has-text-align-center has-theme-palette-9-color has-text-color has-link-color has-xxlarge-font-size\">Seth Kantner</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Stories and photography from life on the land in Northwest Alaska</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {\"overlayColor\":\"theme-palette2\",\"isUserOverlayColor\":true,\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-theme-palette-2-background-color has-background-dim-100 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:image {\"lightbox\":{\"enabled\":false},\"id\":96,\"width\":\"auto\",\"height\":\"500px\",\"sizeSlug\":\"full\",\"linkDestination\":\"custom\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><a href=\"https://pjacobsen.bitlampsites.com/wpd/Final/book/a-thousand-trails-home/\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/trailshome-3.webp\" alt=\"\" class=\"wp-image-96\" style=\"width:auto;height:500px\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette9\"}}}},\"textColor\":\"theme-palette9\"} -->\n<h2 class=\"wp-block-heading has-theme-palette-9-color has-text-color has-link-color\">View Seths Latest Book, Available Now!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette9\"}}}},\"textColor\":\"theme-palette9\"} -->\n<p class=\"has-theme-palette-9-color has-text-color has-link-color\">\"A book to break and restore your heart\"<br>-Louise Eldrich, author of <em>The Night Watchman</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">View The Book</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://www.mountaineers.org/books/books/a-thousand-trails-home-living-with-caribou\">Get The Book</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {\"height\":\"20px\"} -->\n<div style=\"height:20px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:block {\"ref\":86} /-->', 'Home', '', 'publish', 'closed', 'closed', '', 'home', '', '', '2024-10-11 15:25:24', '2024-10-11 15:25:24', '', 0, 'https://pjacobsen.bitlampsites.com/wpd/Final/?page_id=8', 0, 'page', '', 0),
