(21, 1, '2024-09-30 18:39:36', '2024-09-30 18:39:36', '<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Seth Kantner</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaType\":\"image\",\"imageFill\":false} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"blob:https://pjacobsen.bitlampsites.com/ff52fa9a-5000-4984-896e-5884aba67dd2\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Content…\"} -->\n<p>Seth Kantner is an American author and writer who was born in northern Alaska and now lives in Kotzebue, Ak. Outside of his writing he is a commercial fisherman, wildlife photographer and trapper. Seth was school and home and the land he grew up on then attended school at University of Alaska and went on to pursue Journalism and University of Montana.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->', 'Author Bio', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2024-09-30 18:39:36', '2024-09-30 18:39:36', '', 11, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=21', 0, 'revision', '', 0),
