(50, 1, '2024-10-01 15:50:38', '2024-10-01 15:50:38', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"book-image\"} -->\n<figure class=\"wp-block-image size-full book-image\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/trailshome.webp\" alt=\"\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>\"<em>A Thousand Trails Home</em>&nbsp;is a book of supernal majesty, a book to break and restore your heart. Seth Kantner’s devotion to the living pulse and unity of the skein of wonder that is the Alaskan wilderness haunts and inspires me.\"<br><strong>- Louise Erdrich, author of&nbsp;<em>The Night Watchman</em></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get The Book</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'A Thousand Trails Home: Living With Caribou', '', 'publish', 'open', 'open', '', 'a-thousand-trails-home-living-with-caribou', '', '', '2024-10-09 11:59:35', '2024-10-09 11:59:35', '', 0, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=50', 0, 'post', '', 1),
