(52, 1, '2024-10-01 15:50:38', '2024-10-01 15:50:38', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/trailshome.webp\" alt=\"\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>\"<em>A Thousand Trails Home</em> is a book of supernal majesty, a book to break and restore your heart. Seth Kantner’s devotion to the living pulse and unity of the skein of wonder that is the Alaskan wilderness haunts and inspires me.\"<br><strong>- Louise Erdrich, author of <em>The Night Watchman</em></strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'A Thousand Trails Home: Living With Caribou', '', 'inherit', 'closed', 'closed', '', '50-revision-v1', '', '', '2024-10-01 15:50:38', '2024-10-01 15:50:38', '', 50, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=52', 0, 'revision', '', 0),
(53, 1, '2024-10-01 15:54:02', '2024-10-01 15:54:02', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":54,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"book-image\"} -->\n<figure class=\"wp-block-image size-full book-image\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/wolves.webp\" alt=\"\" class=\"wp-image-54\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>\"A rare thing of beauty, a novel alive with detail about a life most of us would never experience.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>- Susan Salter Reynolds,&nbsp;<em>Los Angeles Times Book Review</em></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>\"...A tour de force and may be the best treatment of the Northwest and its people since Jack London\'s works.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em><strong>- Publisher\'s Weekly (starred review)</strong></em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Ordinary Wolves', '', 'publish', 'open', 'open', '', 'ordinary-wolves', '', '', '2024-10-01 15:58:27', '2024-10-01 15:58:27', '', 0, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=53', 0, 'post', '', 0),
