rc=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/trailshome-3.webp\" alt=\"\" class=\"wp-image-96\" style=\"width:auto;height:500px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette9\"}}}},\"textColor\":\"theme-palette9\"} -->\n<h2 class=\"wp-block-heading has-theme-palette-9-color has-text-color has-link-color\">View Seths Latest Book, Available Now!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette9\"}}}},\"textColor\":\"theme-palette9\"} -->\n<p class=\"has-theme-palette-9-color has-text-color has-link-color\">\"A book to break and restore your heart\"<br>-Louise Eldrich, author of <em>The Night Watchman</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://www.mountaineers.org/books/books/a-thousand-trails-home-living-with-caribou\">Get The Book</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->', 'Home', '', 'inherit', 'closed', 'closed', '', '8-revision-v1', '', '', '2024-10-09 11:58:39', '2024-10-09 11:58:39', '', 8, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=124', 0, 'revision', '', 0),
(125, 1, '2024-10-09 11:59:35', '2024-10-09 11:59:35', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"book-image\"} -->\n<figure class=\"wp-block-image size-full book-image\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/trailshome.webp\" alt=\"\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>\"<em>A Thousand Trails Home</em>&nbsp;is a book of supernal majesty, a book to break and restore your heart. Seth Kantner’s devotion to the living pulse and unity of the skein of wonder that is the Alaskan wilderness haunts and inspires me.\"<br><strong>- Louise Erdrich, author of&nbsp;<em>The Night Watchman</em></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get The Book</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'A Thousand Trails Home: Living With Caribou', '', 'inherit', 'closed', 'closed', '', '50-revision-v1', '', '', '2024-10-09 11:59:35', '2024-10-09 11:59:35', '', 50, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=125', 0, 'revision', '', 0),
(126, 1, '2024-10-09 12:00:32', '2024-10-09 12:00:32', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":72,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/pup.webp\" alt=\"\" class=\"wp-image-72\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>A boisterous wolf pup and an awkward young porcupine are unlikely allies in this tale of friendship set on Alaska\'s tundra. The two grow up as neighbors, but only through helping each other escape from a trapper do they learn what it means truly to be friends.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get The Book</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Pup and Pokey', '', 'inherit', 'closed', 'closed', '', '71-revision-v1', '', '', '2024-10-09 12:00:32', '2024-10-09 12:00:32', '', 71, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=126', 0, 'revision', '', 0),
(127, 1, '2024-10-09 12:01:53', '2024-10-09 12:01:53', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":64,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/greatland.webp\" alt=\"\" class=\"wp-image-64\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>\"Kantner\'s, pull-no-punches, head on stories are raw, beautiful and unnerving.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em><strong>- Orion Magazine</strong></em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>\"The stories are spell-binding, the writing magnificent.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em><strong>- Missoulian</strong></em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get The Book</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Swallowed by the Great Land', '', 'inherit', 'closed', 'closed', '', '63-revision-v1', '', '', '2024-10-09 12:01:53', '2024-10-09 12:01:53', '', 63, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=127', 0, 'revision', '', 0),
(128, 1, '2024-10-09 12:02:56', '2024-10-09 12:02:56', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":67,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/porcupine.webp\" alt=\"\" class=\"wp-image-67\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>\"Seth Kantner illuminates an Alaska most of us will never know.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><br><em><strong>- Andrea Barrett, author of Ship Fever and</strong></em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em><strong>The Voyage of the Narwhal</strong></em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>\"Suspense and heartache are matched by wry humor and outrage, and all is infused with Kantner’s humility and deep respect for the wild...Crafted with the precision and nerve acquired by living off the land, this is a powerful and important book of remembrance, protest, and warning.\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><br><em><strong>- Booklist&nbsp;</strong></em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get The Book</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Shopping for Porcupine', '', 'inherit', 'closed', 'closed', '', '66-revision-v1', '', '', '2024-10-09 12:02:56', '2024-10-09 12:02:56', '', 66, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=128', 0, 'revision', '', 0),
