(173, 1, '2024-10-11 15:52:07', '2024-10-11 15:52:07', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":172,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/wolves-1.webp\" alt=\"\" class=\"wp-image-172\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>“A rare thing of beauty, a novel alive with detail about a life most of us would never experience.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>– Susan Salter Reynolds,&nbsp;<em>Los Angeles Times Book Review</em></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>“…A tour de force and may be the best treatment of the Northwest and its people since Jack London’s works.”</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em><strong>– Publisher’s Weekly (starred review)</strong></em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Ordinary Wolves', '', 'inherit', 'closed', 'closed', '', '171-revision-v1', '', '', '2024-10-11 15:52:07', '2024-10-11 15:52:07', '', 171, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=173', 0, 'revision', '', 0),
(174, 1, '2024-10-14 17:52:32', '2024-10-14 17:52:32', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":72,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://pjacobsen.bitlampsites.com/wpd/Final/wp-content/uploads/2024/10/pup.webp\" alt=\"\" class=\"wp-image-72\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>A boisterous wolf pup and an awkward young porcupine are unlikely allies in this tale of friendship set on Alaska\'s tundra. The two grow up as neighbors, but only through helping each other escape from a trapper do they learn what it means truly to be friends.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get The Book</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Pup and Pokey post', '', 'inherit', 'closed', 'closed', '', '71-revision-v1', '', '', '2024-10-14 17:52:32', '2024-10-14 17:52:32', '', 71, 'https://pjacobsen.bitlampsites.com/wpd/Final/?p=174', 0, 'revision', '', 0),
(180, 1, '2024-10-16 18:44:13', '2024-10-16 18:44:13', '<!-- wp:paragraph -->\n<p>This is a review about a book called Ordinary Wolves</p>\n<!-- /wp:paragraph -->', 'asdf', '', 'publish', 'closed', 'closed', '', 'asdf', '', '', '2024-10-16 22:11:57', '2024-10-16 22:11:57', '', 0, 'https://pjacobsen.bitlampsites.com/wpd/Final/?post_type=review&#038;p=180', 0, 'review', '', 0);
